// The CLOSED list of everything the Carousel scenes say out loud ("Where does the teddy go?", "Go get the ball.", "All done!"), in English, and the id each one is
// asked for by. The list is src/lib/scenePrompts.json, GENERATED by `npx tsx scripts/scene-prompts.ts` from the real scene code (scripts/lib/scene-prompts-enum.ts calls
// the same functions the game calls), and `npx tsx scripts/scene-prompts.ts --check` (and tests/scene-prompts.test.ts) fail when the code and the file disagree.
//
// Why a closed list: the voice route (worker/voice.ts, `s=<id>`) takes an ID, never text. It speaks only a line that is in this file, so nothing a child typed or said
// can ever reach the voice model, and the number of clips is the number of lines here (each is made once and then served from the edge cache for a year).
//
// The id is a fingerprint of the text (FNV-1a over its NFC UTF-8 bytes, 8 hex digits: the same function as householdTextHash, kept here so a client does not have to
// load the household names to speak a prompt). A line that is reworded therefore has a NEW id and a new clip; the old clip is simply never asked for again.
import manifest from "./scenePrompts.json";
import { promptId } from "./scenePromptId";

export { promptId };

export interface ScenePrompt {
  id: string;
  text: string;
}

export const SCENE_PROMPTS: readonly ScenePrompt[] = manifest.prompts;

const BY_ID = new Map<string, string>(SCENE_PROMPTS.map((p) => [p.id, p.text]));
const BY_TEXT = new Map<string, string>(SCENE_PROMPTS.map((p) => [p.text, p.id]));

/** True for an id in the list. A Map, so "constructor" and "__proto__" are not ids. */
export function isPromptId(id: unknown): id is string {
  return typeof id === "string" && BY_ID.has(id);
}

/** The English line an id stands for, or null when it is not in the list. */
export function promptText(id: string): string | null {
  return BY_ID.get(id) ?? null;
}

/** The id of a line, matching the text EXACTLY (not trimmed, not re-cased), or null when the game is saying something that is not in the list. */
export function promptIdForText(text: string): string | null {
  return BY_TEXT.get(text) ?? null;
}

/** The URL of a prompt's clip: the same-origin voice route, English, by id. */
export function scenePromptUrl(id: string): string {
  return `/api/voice?${new URLSearchParams({ s: id }).toString()}`;
}
